def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_c = 0
    my_c = 0
    unprovoked = 0
    mutual = 0
    exploited = 0
    for m, o in history:
        if o == 'C':
            opp_c += 1
        if m == 'C':
            my_c += 1
        if m == 'C' and o == 'D':
            unprovoked += 1
        elif m == 'D' and o == 'D':
            mutual += 1
        elif m == 'D' and o == 'C':
            exploited += 1

    opp_d = n - opp_c
    my_d = n - my_c

    recent = history[-8:] if n >= 8 else history
    rl = len(recent)
    recent_opp_d = sum(1 for m, o in recent if o == 'D')
    recent_opp_c = rl - recent_opp_d
    recent_my_d = sum(1 for m, o in recent if m == 'D')
    recent_unprovoked = sum(1 for m, o in recent if m == 'C' and o == 'D')

    ourD_next = 0
    retal = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            ourD_next += 1
            if history[i + 1][1] == 'D':
                retal += 1

    last_mine, last_opp = history[-1]

    if opp_c == 0:
        return 'D'

    if n >= 5 and recent_opp_d == rl and opp_d >= n - 2:
        return 'D'

    if n >= 8 and recent_opp_d >= 6 and opp_d > opp_c and unprovoked >= 3:
        return 'D'

    if unprovoked >= max(5, n // 3) and opp_d >= opp_c:
        return 'D'

    if n >= 6:
        mismatch = 0
        for m, o in history[-6:]:
            if m != o:
                mismatch += 1
        if mismatch >= 5 and unprovoked >= 2 and exploited >= 2:
            return 'D'

    if opp_d == 0:
        if n < 12:
            return 'C'
        if n == 12 and my_d == 0:
            return 'D'
        if n == 13 and my_d == 1 and last_mine == 'D' and last_opp == 'C':
            return 'C'
        return 'D'

    if (my_d >= 3 and ourD_next >= 3 and retal == 0 and unprovoked <= 2 and
            opp_d <= max(1, n // 8) and recent_opp_c >= rl - 2):
        if last_mine == 'D' and last_opp == 'C':
            return 'D'
        if last_mine == 'C' and last_opp == 'C':
            if recent_unprovoked == 0 and recent_my_d >= 2:
                return 'D'
            return 'C'

    if n >= 97:
        if (n == 98 and recent_opp_c == rl and my_d >= 1 and retal > 0 and
                last_mine == 'D' and last_opp == 'C' and opp_c >= opp_d + 3):
            return 'C'
        return 'D'

    if last_mine == 'C' and last_opp == 'D':
        if n >= 2 and history[-2][0] == 'D':
            if recent_opp_d >= 6 or unprovoked >= 5 or opp_d > my_c + 4:
                return 'D'
            return 'C'

        if unprovoked <= 2 and opp_d <= max(2, n // 5) and recent_opp_c >= rl - 2:
            if unprovoked >= 2 and opp_d >= 2:
                if rng.random() < 0.15:
                    return 'C'
            return 'D'

        if recent_opp_d >= 3 or opp_d > opp_c:
            return 'D'

        if recent_opp_d <= 1 and opp_c >= n - 3:
            if rng.random() < 0.1:
                return 'C'
            return 'D'

        return 'D'

    if last_mine == 'D' and last_opp == 'D':
        if recent_opp_d >= 6 or opp_d > opp_c + 3 or unprovoked >= 5:
            return 'D'
        return 'C'

    if last_mine == 'D' and last_opp == 'C':
        if unprovoked == 0 and opp_d == 0:
            return 'D'
        if unprovoked <= 1 and my_d >= 2 and ourD_next >= 2 and retal == 0 and opp_d <= max(1, n // 8):
            return 'D'
        if my_d >= 4 and ourD_next >= 4 and retal == 0 and unprovoked <= 2 and opp_d <= max(1, n // 5):
            return 'D'
        if n >= 70 and my_d <= 2 and opp_d <= 2 and recent_opp_c >= 6 and rng.random() < 0.02:
            return 'D'
        return 'C'

    if last_mine == 'C' and last_opp == 'C':
        if (recent_unprovoked <= 1 and recent_opp_c >= rl - 1 and recent_my_d >= 2 and
                ourD_next >= 2 and retal == 0 and unprovoked <= 2):
            if n < 90 and rng.random() < 0.15:
                return 'D'
            return 'C'
        return 'C'

    if recent_opp_c >= recent_opp_d:
        return 'C'
    if rng.random() < 0.1:
        return 'C'
    return 'D'
